            balance -= amount;
        }
        double getBalance() { return balance; }
    }
    public static void main(String[] args) {
        BankAccount acc = new BankAccount();
        acc.deposit(1000); acc.withdraw(250);
        System.out.println("Balance: " + acc.getBalance());
        acc.withdraw(1000);
        System.out.println("Balance: " + acc.getBalance());
    }
}

