exception-handling.solution:
public class Main {
    static class PaymentException extends RuntimeException { PaymentException(String m) { super(m); } }
    static class InsufficientFundsException extends PaymentException { InsufficientFundsException(double a, double b) { super("Need " + a + " but only have " + b); } }
    static void processPayment(double amount, double balance) throws PaymentException {
        if (amount <= 0) throw new PaymentException("Amount must be positive");
        if (amount > balance) throw new InsufficientFundsException(amount, balance);
        System.out.println("Payment of " + amount + " processed");
    }
    public static void main(String[] args) {
        try { processPayment(500, 200); }
        catch (InsufficientFundsException e) { System.out.println("Funds error: " + e.getMessage()); }
        catch (PaymentException e) { System.out.println("Payment error: " + e.getMessage()); }
        try { processPayment(-10, 200); }
        catch (InsufficientFundsException e) { System.out.println("Funds error: " + e.getMessage()); }
        catch (PaymentException e) { System.out.println("Payment error: " + e.getMessage()); }
    }
}

