import java.util.*;
public class Main {
    static class Stack<T> {
        private List<T> list = new ArrayList<>();
        void push(T item) { list.add(item); }
        T pop() { if (isEmpty()) throw new RuntimeException("Empty"); return list.remove(list.size()-1); }
        T peek() { if (isEmpty()) throw new RuntimeException("Empty"); return list.get(list.size()-1); }
        boolean isEmpty() { return list.isEmpty(); }
    }
    public static void main(String[] args) {
        Stack<Integer> s = new Stack<>();
        s.push(10); s.push(20); s.push(30);
        System.out.println(s.pop());
        System.out.println(s.peek());
        System.out.println(s.isEmpty());
    }
}

