public class Main {
    interface EmailService { void sendEmail(String to, String subject); }
    interface Logger { void log(String message); }
    static class SmtpEmailService implements EmailService {
        public void sendEmail(String to, String subject) { System.out.println("Email sent to " + to + ": " + subject); }
    }
    static class ConsoleLogger implements Logger {
        public void log(String message) { System.out.println("[LOG] " + message); }
    }
    static class UserService {
        private final EmailService emailService;
        private final Logger logger;
        UserService(EmailService e, Logger l) { emailService = e; logger = l; }
        void registerUser(String email) {
            logger.log("Registering: " + email);
            emailService.sendEmail(email, "Welcome!");
            System.out.println("User registered: " + email);
        }
    }
    public static void main(String[] args) {
        UserService service = new UserService(new SmtpEmailService(), new ConsoleLogger());
        service.registerUser("alice@example.com");
    }
}

