import java.lang.annotation.*;
import java.lang.reflect.*;
public class Main {
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.FIELD)
    @interface Validate { int minLength() default 1; }
    static class User {
        @Validate(minLength = 3) String username;
        @Validate(minLength = 6) String password;
        User(String u, String p) { username = u; password = p; }
    }
    static boolean validate(Object obj) throws IllegalAccessException {
        for (Field f : obj.getClass().getDeclaredFields()) {
            f.setAccessible(true);
            Validate v = f.getAnnotation(Validate.class);
            if (v != null) {
                String val = (String) f.get(obj);
                if (val == null || val.length() < v.minLength()) {
                    System.out.println("Invalid: " + f.getName());
                    return false;
                }
            }
        }
        return true;
    }
    public static void main(String[] args) throws Exception {
        System.out.println(validate(new User("Al", "secret123")));
        System.out.println(validate(new User("Alice", "secret123")));
    }
}

