import java.util.Base64;
public class Main {
    public static void main(String[] args) {
        String header = "{\"alg\":\"HS256\",\"typ\":\"JWT\"}";
        String payload = "{\"sub\":\"user123\",\"role\":\"ADMIN\"}";
        String encHeader = Base64.getUrlEncoder().withoutPadding().encodeToString(header.getBytes());
        String encPayload = Base64.getUrlEncoder().withoutPadding().encodeToString(payload.getBytes());
        String token = encHeader + "." + encPayload + "." + "signature";
        System.out.println("Token: " + token);
        String[] parts = token.split("\\.");
        System.out.println(new String(Base64.getUrlDecoder().decode(parts[0])));
        System.out.println(new String(Base64.getUrlDecoder().decode(parts[1])));
    }
}

