public class Main {
    static class ApiRequest { String method, url, body; ApiRequest(String m, String u, String b) { method=m; url=u; body=b; } }
    static class ApiResponse { int statusCode; String body; ApiResponse(int c, String b) { statusCode=c; body=b; } public String toString() { return statusCode + " " + body; } }
    static ApiResponse processRequest(ApiRequest req) {
        return switch (req.method) {
            case "GET" -> new ApiResponse(200, "OK");
            case "POST" -> new ApiResponse(201, "Created");
            default -> new ApiResponse(405, "Method Not Allowed");
        };
    }
    public static void main(String[] args) {
        System.out.println(processRequest(new ApiRequest("GET","/users",null)));
        System.out.println(processRequest(new ApiRequest("POST","/users","{}")));
        System.out.println(processRequest(new ApiRequest("DELETE","/users/1",null)));
    }
}
